  static final Map<String, TemplateInfo> _templates = {
    for (final c in categories)
      for (final id in c.templateIds) id: TemplateInfo(id: id, title: _titles[id]!, categoryId: c.id),
  };

  static List<TemplateInfo> get allTemplates => _templates.values.toList(growable: false);

  static TemplateInfo? template(String id) => _templates[id];

  static ColoringCategory? category(String id) {
    for (final c in categories) {
      if (c.id == id) return c;
    }
    return null;
  }

  static List<TemplateInfo> templatesIn(String categoryId) =>
      category(categoryId)?.templateIds.map((id) => _templates[id]!).toList() ?? const [];
}
